-- PromRegion56 / PostgreSQL 13+ / Новотроицк, Орск, Оренбург.
-- Dataset is compiled from the previously supplied 2021-2025 CSV bundles.
-- Company rule: at least one indicator observed in >=3 DISTINCT years, 2021-2025.
-- Indicator rule: all series with <3 years are dropped, regardless of other metrics.
-- Data quality: previous source_linked_legacy entries ARE NOT independently audited here.
-- For a FRESH EMPTY database only. Does not fetch data and does not update GitHub Pages.

BEGIN;
DO $check_fresh$
BEGIN
 IF to_regclass('public.cities') IS NOT NULL THEN
   RAISE EXCEPTION 'Database not empty: use a NEW PostgreSQL database, or the explicit replacement script.';
 END IF;
END $check_fresh$;
CREATE TABLE public.cities (
 id integer PRIMARY KEY, name varchar(150) NOT NULL UNIQUE, region varchar(150) NOT NULL,
 district varchar(150), latitude double precision, longitude double precision,
 territory_type varchar(100), oktmo varchar(20), administrative_center varchar(150),
 CONSTRAINT cities_allowed_only_three CHECK(name IN ('Новотроицк','Орск','Оренбург')));
CREATE TABLE public.industries (id integer PRIMARY KEY, name varchar(200) NOT NULL UNIQUE, description text);
CREATE TABLE public.data_sources (
 id integer PRIMARY KEY, name varchar(255) NOT NULL, url text,
 source_type varchar(100), publication_date date, access_date date, description text);
CREATE TABLE public.enterprises (
 id integer PRIMARY KEY, name varchar(255) NOT NULL, short_name varchar(250),
 inn varchar(12), ogrn varchar(15), city_id integer NOT NULL REFERENCES public.cities(id) ON UPDATE CASCADE ON DELETE RESTRICT,
 industry_id integer NOT NULL REFERENCES public.industries(id) ON UPDATE CASCADE ON DELETE RESTRICT,
 okved varchar(20), address text, activity_description text, products text, website varchar(255),
 phone varchar(50), email varchar(150), latitude double precision, longitude double precision,
 status varchar(50), foundation_year integer, employee_category varchar(100),
 is_city_forming boolean DEFAULT false, is_major_enterprise boolean DEFAULT false, economic_role varchar(150));
CREATE TABLE public.enterprise_metrics (
 id integer PRIMARY KEY, enterprise_id integer NOT NULL REFERENCES public.enterprises(id) ON UPDATE CASCADE ON DELETE CASCADE,
 year integer NOT NULL CHECK(year BETWEEN 2021 AND 2025), employees integer,
 revenue numeric, investments numeric, average_salary numeric,
 source_id integer REFERENCES public.data_sources(id) ON UPDATE CASCADE ON DELETE SET NULL,
 net_profit numeric, assets numeric, taxes_paid numeric, production_volume numeric,
 revenue_estimation_method text, CONSTRAINT uq_enterprise_year UNIQUE(enterprise_id,year));
CREATE TABLE public.enterprise_products (
 id integer PRIMARY KEY, enterprise_id integer NOT NULL REFERENCES public.enterprises(id) ON DELETE CASCADE,
 product_name varchar(255) NOT NULL, product_category varchar(150), description text,
 is_main boolean DEFAULT false, source_id integer REFERENCES public.data_sources(id) ON UPDATE CASCADE ON DELETE SET NULL,
 CONSTRAINT uq_enterprise_products_enterprise_product UNIQUE(enterprise_id,product_name));
CREATE TABLE public.enterprise_sources (
 id integer PRIMARY KEY, enterprise_id integer NOT NULL REFERENCES public.enterprises(id) ON UPDATE CASCADE ON DELETE CASCADE,
 source_id integer NOT NULL REFERENCES public.data_sources(id) ON UPDATE CASCADE ON DELETE CASCADE,
 source_role varchar(100), notes text, CONSTRAINT uq_enterprise_source UNIQUE(enterprise_id,source_id));
CREATE TABLE public.territory_metrics (
 id integer PRIMARY KEY, city_id integer REFERENCES public.cities(id) ON UPDATE CASCADE ON DELETE RESTRICT,
 year integer NOT NULL CHECK(year BETWEEN 2021 AND 2025), population integer,
 average_salary numeric(12,2), unemployment_rate numeric(5,2), investments numeric(18,2),
 industrial_output numeric(18,2), employed_population integer, enterprises_count integer,
 industrial_enterprises_count integer,
 source_id integer REFERENCES public.data_sources(id) ON UPDATE CASCADE ON DELETE SET NULL,
 CONSTRAINT uq_territory_city_year UNIQUE(city_id,year));
CREATE TABLE public.investment_projects (
 id integer PRIMARY KEY, name varchar(255) NOT NULL,
 city_id integer REFERENCES public.cities(id) ON UPDATE CASCADE ON DELETE SET NULL,
 enterprise_id integer REFERENCES public.enterprises(id) ON UPDATE CASCADE ON DELETE SET NULL,
 industry_id integer REFERENCES public.industries(id) ON UPDATE CASCADE ON DELETE SET NULL,
 status char(100), start_year integer, end_year integer,
 investment_amount numeric(18,0), jobs_created integer, description text,
 source_id integer REFERENCES public.data_sources(id) ON UPDATE CASCADE ON DELETE SET NULL);
CREATE TABLE public.enterprise_metric_quality (
 enterprise_id integer NOT NULL REFERENCES public.enterprises(id) ON DELETE CASCADE,
 year integer NOT NULL CHECK(year BETWEEN 2021 AND 2025), indicator varchar(40) NOT NULL,
 quality_status text NOT NULL, note text,
 PRIMARY KEY(enterprise_id,year,indicator));
CREATE TABLE public.city_annual_indicators (
 city_id integer NOT NULL REFERENCES public.cities(id), year integer NOT NULL CHECK(year BETWEEN 2021 AND 2025),
 metric_code text NOT NULL, numeric_value numeric(20,4), unit text NOT NULL,
 source_metric_name text NOT NULL,
 verification_status text NOT NULL CHECK(verification_status IN ('reported','municipal_estimate','unavailable')),
 source_id integer REFERENCES public.data_sources(id), as_of_date date, coverage_note text NOT NULL DEFAULT '',
 PRIMARY KEY(city_id,year,metric_code));

-- Data rows; all enterprise indicators satisfy >= 3 distinct years.








-- no rows in investment_projects



CREATE INDEX idx_enterprise_metrics_year ON public.enterprise_metrics(year);
CREATE INDEX idx_enterprise_products_enterprise ON public.enterprise_products(enterprise_id);
CREATE INDEX idx_enterprises_city ON public.enterprises(city_id);
CREATE INDEX idx_enterprises_industry ON public.enterprises(industry_id);
CREATE INDEX idx_enterprises_status ON public.enterprises(status);
CREATE INDEX idx_city_annual_indicators_code ON public.city_annual_indicators(city_id,metric_code,year);
CREATE VIEW public.v_promregion56_metric_coverage AS
 SELECT e.city_id,e.id AS enterprise_id,e.short_name AS enterprise,
        u.indicator, COUNT(*)::integer AS years_available,
        MIN(em.year)::integer AS first_year,MAX(em.year)::integer AS last_year
 FROM public.enterprises e
 JOIN public.enterprise_metrics em ON em.enterprise_id=e.id
 CROSS JOIN LATERAL (VALUES
  ('revenue',em.revenue),('net_profit',em.net_profit),('assets',em.assets),
  ('employees',em.employees::numeric),('investments',em.investments),
  ('average_salary',em.average_salary),('taxes_paid',em.taxes_paid),
  ('production_volume',em.production_volume)) AS u(indicator,metric_value)
 WHERE u.metric_value IS NOT NULL AND em.year BETWEEN 2021 AND 2025
 GROUP BY e.city_id,e.id,e.short_name,u.indicator
 HAVING COUNT(DISTINCT em.year)>=3;
CREATE VIEW public.v_promregion56_metric_series AS
 SELECT e.city_id,e.id AS enterprise_id,e.short_name AS enterprise,em.year,
  u.indicator,u.metric_value AS value,q.quality_status
 FROM public.enterprises e
 JOIN public.enterprise_metrics em ON em.enterprise_id=e.id
 CROSS JOIN LATERAL (VALUES
  ('revenue',em.revenue),('net_profit',em.net_profit),('assets',em.assets),
  ('employees',em.employees::numeric),('investments',em.investments),
  ('average_salary',em.average_salary),('taxes_paid',em.taxes_paid),
  ('production_volume',em.production_volume)) AS u(indicator,metric_value)
 JOIN public.v_promregion56_metric_coverage cov
   ON cov.enterprise_id=e.id AND cov.indicator=u.indicator
 LEFT JOIN public.enterprise_metric_quality q
   ON q.enterprise_id=e.id AND q.year=em.year AND q.indicator=u.indicator
 WHERE u.metric_value IS NOT NULL;
CREATE VIEW public.v_promregion56_enterprises AS
 SELECT e.*,c.name AS city_name
 FROM public.enterprises e JOIN public.cities c ON c.id=e.city_id
 WHERE c.name IN ('Орск','Новотроицк','Оренбург')
 AND EXISTS(SELECT 1 FROM public.v_promregion56_metric_coverage cov WHERE cov.enterprise_id=e.id);
-- Safe-insertion restriction: only these three cities and years 2021-2025 are valid.
-- All PKs are imported explicitly, so create sequences with the original project names.
CREATE SEQUENCE IF NOT EXISTS public.cities_id_seq AS integer OWNED BY public.cities.id;
ALTER TABLE public.cities ALTER COLUMN id SET DEFAULT nextval('public.cities_id_seq'::regclass);
SELECT setval('public.cities_id_seq', 3, true);
CREATE SEQUENCE IF NOT EXISTS public.industries_id_seq AS integer OWNED BY public.industries.id;
ALTER TABLE public.industries ALTER COLUMN id SET DEFAULT nextval('public.industries_id_seq'::regclass);
SELECT setval('public.industries_id_seq', 8, true);
CREATE SEQUENCE IF NOT EXISTS public.data_sources_id_seq AS integer OWNED BY public.data_sources.id;
ALTER TABLE public.data_sources ALTER COLUMN id SET DEFAULT nextval('public.data_sources_id_seq'::regclass);
SELECT setval('public.data_sources_id_seq', 71, true);
CREATE SEQUENCE IF NOT EXISTS public.enterprises_id_seq AS integer OWNED BY public.enterprises.id;
ALTER TABLE public.enterprises ALTER COLUMN id SET DEFAULT nextval('public.enterprises_id_seq'::regclass);
SELECT setval('public.enterprises_id_seq', 1103, true);
CREATE SEQUENCE IF NOT EXISTS public.enterprise_metrics_id_seq AS integer OWNED BY public.enterprise_metrics.id;
ALTER TABLE public.enterprise_metrics ALTER COLUMN id SET DEFAULT nextval('public.enterprise_metrics_id_seq'::regclass);
SELECT setval('public.enterprise_metrics_id_seq', 180, true);
CREATE SEQUENCE IF NOT EXISTS public.enterprise_products_id_seq AS integer OWNED BY public.enterprise_products.id;
ALTER TABLE public.enterprise_products ALTER COLUMN id SET DEFAULT nextval('public.enterprise_products_id_seq'::regclass);
SELECT setval('public.enterprise_products_id_seq', 93, true);
CREATE SEQUENCE IF NOT EXISTS public.enterprise_sources_id_seq AS integer OWNED BY public.enterprise_sources.id;
ALTER TABLE public.enterprise_sources ALTER COLUMN id SET DEFAULT nextval('public.enterprise_sources_id_seq'::regclass);
SELECT setval('public.enterprise_sources_id_seq', 69, true);
CREATE SEQUENCE IF NOT EXISTS public.territory_metrics_id_seq AS integer OWNED BY public.territory_metrics.id;
ALTER TABLE public.territory_metrics ALTER COLUMN id SET DEFAULT nextval('public.territory_metrics_id_seq'::regclass);
SELECT setval('public.territory_metrics_id_seq', 15, true);
CREATE SEQUENCE IF NOT EXISTS public.investment_projects_id_seq AS integer OWNED BY public.investment_projects.id;
ALTER TABLE public.investment_projects ALTER COLUMN id SET DEFAULT nextval('public.investment_projects_id_seq'::regclass);
SELECT setval('public.investment_projects_id_seq', 1, false);

DO $validate$
BEGIN
 IF (SELECT COUNT(*) FROM public.cities)<>3 OR
    (SELECT COUNT(*) FROM public.enterprises)<>39 THEN
     RAISE EXCEPTION 'Unexpected city or enterprise count in three-city load';
 END IF;
 IF EXISTS (
  SELECT 1 FROM public.enterprises e
  WHERE NOT EXISTS(SELECT 1 FROM public.v_promregion56_metric_coverage c WHERE c.enterprise_id=e.id)
 ) THEN RAISE EXCEPTION 'Enterprise has no metric with 3+ observed years'; END IF;
 IF EXISTS (SELECT 1 FROM public.enterprise_sources GROUP BY enterprise_id HAVING COUNT(*)>2) THEN
    RAISE EXCEPTION 'Source limit exceeded'; END IF;
END $validate$;
COMMIT;


-- PromRegion56 v6 · 2026-11-22 · ПАКЕТ ПРОВЕРЕННЫХ ПОКАЗАТЕЛЕЙ e-ecolog.ru и ССЧ
-- Только Новотроицк, Орск, Оренбург; только предприятия, прошедшие исходный фильтр 3 лет.
-- Дополняет базу; не удаляет прежние данные. Применять ПОСЛЕ industrial_city_db.sql
-- e-ecolog код 384: в источнике ТЫСЯЧИ рублей. amount_rub=original_thousand_rub*1000.
-- Информация о работниках — СРЕДНЕСПИСОЧНАЯ численность за указанный год, НЕ моментальная.
BEGIN;
CREATE TABLE IF NOT EXISTS public.eecolog_financial_facts (
 enterprise_id integer NOT NULL REFERENCES public.enterprises(id) ON DELETE CASCADE,
 inn varchar(12) NOT NULL, report_year integer NOT NULL CHECK(report_year BETWEEN 2021 AND 2025),
 indicator text NOT NULL CHECK(indicator IN ('revenue','net_profit','assets','cost_of_sales','operating_profit','profit_before_tax')),
 amount_rub numeric NOT NULL, original_thousand_rub numeric NOT NULL, source_year integer NOT NULL CHECK(source_year BETWEEN 2021 AND 2025),
 source_url text NOT NULL, source_status text NOT NULL DEFAULT 'source_checked', note text,
 PRIMARY KEY (enterprise_id, report_year, indicator),
 CONSTRAINT check_eecolog_unit CHECK(amount_rub = original_thousand_rub * 1000)
);
CREATE INDEX IF NOT EXISTS idx_eecolog_facts_lookups ON public.eecolog_financial_facts(enterprise_id,indicator,report_year);
CREATE TABLE IF NOT EXISTS public.enterprise_staff_annual (
 enterprise_id integer NOT NULL REFERENCES public.enterprises(id) ON DELETE CASCADE,
 inn varchar(12) NOT NULL, report_year integer NOT NULL CHECK(report_year BETWEEN 2021 AND 2025),
 headcount integer NOT NULL CHECK(headcount >= 0),
 source_url text NOT NULL, headcount_definition text NOT NULL DEFAULT 'Среднесписочная численность за год',
 PRIMARY KEY (enterprise_id,report_year)
);
CREATE OR REPLACE VIEW public.v_enterprise_staff_latest AS
 SELECT DISTINCT ON (s.enterprise_id) s.enterprise_id, e.name, e.city_id, s.report_year, s.headcount, s.source_url, s.headcount_definition
 FROM public.enterprise_staff_annual s JOIN public.enterprises e ON e.id = s.enterprise_id
 ORDER BY s.enterprise_id,s.report_year DESC;
CREATE OR REPLACE VIEW public.v_eecolog_eligible_metrics AS
 SELECT f.* FROM public.eecolog_financial_facts f
 WHERE (SELECT COUNT(DISTINCT report_year) FROM public.eecolog_financial_facts t
        WHERE t.enterprise_id=f.enterprise_id AND t.indicator=f.indicator) >= 3
 OR EXISTS (SELECT 1 FROM public.enterprise_metrics em
  WHERE em.enterprise_id=f.enterprise_id AND em.year BETWEEN 2021 AND 2025
    AND CASE f.indicator WHEN 'revenue' THEN em.revenue WHEN 'net_profit' THEN em.net_profit
     WHEN 'assets' THEN em.assets ELSE NULL END IS NOT NULL
  GROUP BY em.enterprise_id HAVING COUNT(DISTINCT em.year)>=3);
-- В исходном enterprise_metrics сохраняем только проверенные факты для его штатных колонок.
-- Обновляем revenue/profit/assets в существующих строках, не трогая остальное.
UPDATE public.enterprise_metrics em SET
 revenue = COALESCE((SELECT f.amount_rub FROM public.v_eecolog_eligible_metrics f WHERE f.enterprise_id=em.enterprise_id AND f.report_year=em.year AND f.indicator='revenue'),em.revenue),
 net_profit = COALESCE((SELECT f.amount_rub FROM public.v_eecolog_eligible_metrics f WHERE f.enterprise_id=em.enterprise_id AND f.report_year=em.year AND f.indicator='net_profit'),em.net_profit),
 assets = COALESCE((SELECT f.amount_rub FROM public.v_eecolog_eligible_metrics f WHERE f.enterprise_id=em.enterprise_id AND f.report_year=em.year AND f.indicator='assets'),em.assets)
WHERE EXISTS (SELECT 1 FROM public.v_eecolog_eligible_metrics f WHERE f.enterprise_id=em.enterprise_id AND f.report_year=em.year);
-- Численность в исходную годовую таблицу попадает только при наличии >=3 отчетных лет.
UPDATE public.enterprise_metrics em SET employees = s.headcount FROM public.enterprise_staff_annual s
WHERE s.enterprise_id=em.enterprise_id AND s.report_year=em.year
 AND (SELECT COUNT(DISTINCT observation_year) FROM (
  SELECT year AS observation_year FROM public.enterprise_metrics WHERE enterprise_id=s.enterprise_id AND employees IS NOT NULL
  UNION SELECT report_year AS observation_year FROM public.enterprise_staff_annual WHERE enterprise_id=s.enterprise_id
 ) years_union)>=3;
-- Не допускаем населенные пункты вне трех разрешенных.
DO $validate$ BEGIN
 IF EXISTS (SELECT 1 FROM public.cities WHERE name NOT IN ('Новотроицк','Орск','Оренбург')) THEN
  RAISE EXCEPTION 'В базе обнаружены города вне разрешенного списка';
 END IF;
 IF EXISTS(SELECT 1 FROM public.eecolog_financial_facts f JOIN public.enterprises e ON e.id=f.enterprise_id WHERE e.inn IS DISTINCT FROM f.inn) THEN
  RAISE EXCEPTION 'Расхождение ИНН предприятия и отчётности';
 END IF;
 IF EXISTS(SELECT 1 FROM public.enterprise_staff_annual s JOIN public.enterprises e ON e.id=s.enterprise_id WHERE e.inn IS DISTINCT FROM s.inn) THEN
  RAISE EXCEPTION 'Расхождение ИНН при численности';
 END IF;
END $validate$;
COMMIT;
-- PromRegion56 v7 | Новые требования: два НЕнулевых наблюдения в разных годах 2021-2025.
-- Отчёт Михаила: дополнительные статьи БФО; ООО «Инженерные Технологии» исключено.
-- Для существующей БД: применить после v6. Проверить на копии!
BEGIN;
ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description;
CREATE TABLE IF NOT EXISTS public.v7_metric_observations (
 enterprise_id integer NOT NULL REFERENCES public.enterprises(id) ON DELETE CASCADE,
 period_year integer NOT NULL CHECK(period_year BETWEEN 2021 AND 2025),
 metric_code varchar(80) NOT NULL,
 value_numeric numeric NOT NULL,
 source_url text NOT NULL,
 evidence_status varchar(50) NOT NULL,
 precision_kind varchar(60) NOT NULL,
 note text,
 PRIMARY KEY(enterprise_id,period_year,metric_code),
 CONSTRAINT v7_metric_nonzero CHECK (value_numeric <> 0),
 CONSTRAINT v7_source_http CHECK (source_url LIKE 'https://%' OR source_url LIKE 'http://%')
);
CREATE TABLE IF NOT EXISTS public.v7_metric_definitions (
 metric_code varchar(80) PRIMARY KEY, title text NOT NULL, unit varchar(50) NOT NULL, category varchar(80) NOT NULL
);
CREATE TABLE IF NOT EXISTS public.v7_company_sources (
 enterprise_id integer NOT NULL REFERENCES public.enterprises(id) ON DELETE CASCADE,
 source_no integer NOT NULL CHECK(source_no IN (1,2)),
 source_url text NOT NULL,
 source_role varchar(40) NOT NULL,
 PRIMARY KEY(enterprise_id,source_no)
);
-- Удаляем карточки без подходящих рядов из исходного набора (каскадно очищаются дочерние записи).
DELETE FROM public.enterprises WHERE id=88 AND name ILIKE '%Инженерные Технологии%';
DELETE FROM public.enterprises WHERE id=34 AND name ILIKE '%РОСЭлектрод%';
-- Новые карточки, прошедшие критерий двух отчётных лет.

CREATE OR REPLACE VIEW public.v7_eligible_metric_series AS
 SELECT x.enterprise_id, x.metric_code,COUNT(DISTINCT x.period_year)::integer AS years_available,
        MIN(x.period_year) AS min_year,MAX(x.period_year) AS max_year
 FROM public.v7_metric_observations x
 WHERE x.value_numeric IS NOT NULL AND x.value_numeric <> 0
 GROUP BY x.enterprise_id,x.metric_code
 HAVING COUNT(DISTINCT x.period_year)>=2;
CREATE OR REPLACE VIEW public.v7_public_metric_values AS
 SELECT m.*,d.title,d.unit,d.category,e.city_id,e.name AS enterprise_name,e.inn
 FROM public.v7_metric_observations m
 JOIN public.v7_eligible_metric_series s
   ON s.enterprise_id=m.enterprise_id AND s.metric_code=m.metric_code
 JOIN public.enterprises e ON e.id=m.enterprise_id
 JOIN public.v7_metric_definitions d ON d.metric_code=m.metric_code
 JOIN public.cities c ON c.id=e.city_id
 WHERE c.name IN ('Новотроицк','Орск','Оренбург');
CREATE OR REPLACE VIEW public.v7_public_enterprises AS
 SELECT e.* FROM public.enterprises e
 WHERE e.id IN (SELECT DISTINCT enterprise_id FROM public.v7_eligible_metric_series)
 AND e.id NOT IN (88)
 AND e.city_id IN (SELECT id FROM public.cities WHERE name IN ('Новотроицк','Орск','Оренбург'));
CREATE OR REPLACE VIEW public.v7_staff_latest AS
 SELECT DISTINCT ON (s.enterprise_id) s.enterprise_id,s.report_year,s.headcount,s.source_url,s.headcount_definition
 FROM public.enterprise_staff_annual s
 JOIN public.v7_public_enterprises e ON e.id=s.enterprise_id
 WHERE s.headcount>0
 ORDER BY s.enterprise_id,s.report_year DESC;
-- Audit: enforce source count and valid geography in view.
DO $v7validate$
BEGIN
 IF EXISTS (SELECT 1 FROM public.v7_public_enterprises e LEFT JOIN public.v7_eligible_metric_series s ON s.enterprise_id=e.id WHERE s.enterprise_id IS NULL)
  THEN RAISE EXCEPTION 'Enterprise without eligible metric in v7';END IF;
 IF EXISTS (SELECT 1 FROM public.v7_eligible_metric_series WHERE years_available<2)
  THEN RAISE EXCEPTION 'Metric threshold failed in v7';END IF;
 IF EXISTS (SELECT 1 FROM public.v7_company_sources GROUP BY enterprise_id HAVING COUNT(*)>2)
  THEN RAISE EXCEPTION 'More than two sources';END IF;
END $v7validate$;
COMMIT;
